// Acepta el cuerpo plano { client_id, accion, fecha, hora, email, contacto }.
// La normalización del formato propio de Vapi se hará en su propio workflow.
const body = $json.body || $json || {};
const clientId = String(body.client_id || '').trim();

return [{
  json: {
    client_id: clientId,
    // Sin un uuid válido no tiene sentido consultar Supabase: la query
    // devolvería 'invalid input syntax for type uuid' y la ejecución fallaría.
    cliente_valido: /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i.test(clientId),
    accion: String(body.accion || 'disponibilidad').trim().toLowerCase(),
    fecha: body.fecha || null,
    hora: body.hora || null,
    email: body.email || null,
    contacto: String(body.contacto || '').trim(),
    // Servicio o motivo de la cita: va al título del evento del calendario.
    motivo: String(body.motivo || '').trim(),
  },
}];

return [{
  json: {
    ok: false,
    motivo: 'cliente_desconocido',
    mensaje: 'No encuentro la configuración de este negocio. Avisa al administrador.',
  },
}];

const pet = $('Leer petición').first().json;
const cal = $('Buscar módulo calendar').first().json.config || {};
const freeBusy = $('Cargar ocupación').first().json || {};

// --- Horario de atencion del negocio (configurado en el panel) ---------------
// Los valores por defecto deben coincidir con HORARIO_POR_DEFECTO del panel.
const diasLaborables = (cal.dias_laborables || '1,2,3,4,5')
  .split(',')
  .map((s) => parseInt(s, 10))
  .filter((n) => n >= 1 && n <= 7);

// duracion = lo que ocupa la cita. paso = cada cuanto puede empezar una.
// Son cosas distintas: citas de 60 min con paso de 15 permiten reservar a las 10:15.
const duracion = parseInt(cal.duracion_min || '60', 10);
const paso = parseInt(cal.paso_min || '15', 10);

const tramos = [];
if (cal.manana_inicio && cal.manana_fin) tramos.push([cal.manana_inicio, cal.manana_fin]);
if (cal.tarde_inicio && cal.tarde_fin) tramos.push([cal.tarde_inicio, cal.tarde_fin]);
if (!tramos.length) tramos.push(['09:00', '14:00'], ['16:00', '20:00']);

// --- Franjas ya ocupadas segun Google Calendar -------------------------------
const ocupadas = [];
for (const c of Object.values((freeBusy || {}).calendars || {})) {
  for (const b of c.busy || []) {
    ocupadas.push([new Date(b.start).getTime(), new Date(b.end).getTime()]);
  }
}
const solapa = (ini, fin) => ocupadas.some(([a, b]) => ini < b && fin > a);

// --- Huecos realmente libres de los proximos 7 dias --------------------------
const ahora = $now.toMillis();
const libres = [];
for (let i = 0; i < 7; i++) {
  const dia = $now.plus({ days: i }).startOf('day');
  if (!diasLaborables.includes(dia.weekday)) continue;

  const horas = [];
  for (const [desde, hasta] of tramos) {
    const [h1, m1] = desde.split(':').map(Number);
    const [h2, m2] = hasta.split(':').map(Number);
    const cierre = dia.set({ hour: h2, minute: m2 });
    let t = dia.set({ hour: h1, minute: m1 });
    while (t.plus({ minutes: duracion }) <= cierre) {
      const ini = t.toMillis();
      const fin = t.plus({ minutes: duracion }).toMillis();
      if (ini > ahora && !solapa(ini, fin)) horas.push(t.toFormat('HH:mm'));
      t = t.plus({ minutes: paso });
    }
  }
  if (horas.length) {
    libres.push({
      fecha: dia.toFormat('yyyy-MM-dd'),
      dia: dia.setLocale('es').toFormat('cccc'),
      horas,
    });
  }
}

return [{ json: { ...pet, libres, duracion, paso } }];

const d = $input.first().json;

const aMin = (h) => { const [a, b] = h.split(':').map(Number); return a * 60 + b; };
const dosCifras = (n) => String(n).padStart(2, '0');
const aTexto = (m) => dosCifras(Math.floor(m / 60)) + ':' + dosCifras(m % 60);

// La hora que el usuario escribe manda sobre la que extrae la IA: se la ha visto
// devolver time=null con la hora delante, y coger la primera opcion de su propia
// lista de alternativas (le pides 12:30 y reserva 12:15).
function horaDelTexto(txt) {
  const t = String(txt || '').toLowerCase();
  // Se evita el punto como separador suelto: '4.08' es una fecha, no las 04:08.
  const patrones = [
    /\blas\s+(\d{1,2})(?:\s*[:.,'’h]\s*(\d{2}))?/,
    /\b(\d{1,2})\s*[:'’]\s*(\d{2})\b/,
    /\b(\d{1,2})\s*[.,]\s*(\d{2})\s*h\b/,
    /\b(\d{1,2})\s*h\s*(\d{2})\b/,
    /\b(\d{1,2})\s*h\b/,
  ];
  for (const p of patrones) {
    const m = t.match(p);
    if (!m) continue;
    const h = Number(m[1]);
    const min = m[2] === undefined ? 0 : Number(m[2]);
    if (h < 24 && min < 60) return dosCifras(h) + ':' + dosCifras(min);
  }
  return null;
}

const libres = d.libres || [];
const fecha = d.fecha;
// Normalizamos la hora por si llega como "12h30" o "12'30" desde el agente de voz.
const hora = d.hora ? horaDelTexto(String(d.hora)) || String(d.hora) : null;

// El email es opcional: por teléfono el reconocimiento de voz lo destroza a
// menudo, y quedarse sin cita por eso es peor que quedarse sin confirmación.
// Si no tiene pinta de email válido, lo tratamos como que no lo hay.
const email = /^[^\s@]+@[^\s@]+\.[a-z]{2,}$/i.test(String(d.email || '').trim())
  ? String(d.email).trim()
  : '';

if (!fecha || !hora) {
  return [{ json: { ...d, hora, email, estado: 'faltan_datos' } }];
}

const dia = libres.find((d) => d.fecha === fecha);
const libre = Boolean(dia && dia.horas.includes(hora));

// Las alternativas son las mas CERCANAS a la hora pedida: la ultima que cabe
// antes y varias despues. Ofrecer las primeras horas del dia a quien pide las
// 12:00 no le sirve de nada.
const pedido = aMin(hora);
const cercanas = (horas, nDespues) => {
  const antes = horas.filter((h) => aMin(h) < pedido).slice(-1);
  const despues = horas.filter((h) => aMin(h) > pedido).slice(0, nDespues);
  return antes.concat(despues);
};

const alternativas = [];
if (dia && dia.horas.length) {
  alternativas.push({ fecha: dia.fecha, dia: dia.dia, horas: cercanas(dia.horas, 4) });
}
for (const d of libres) {
  if (alternativas.length >= 3) break;
  if (d.fecha === fecha || !d.horas.length) continue;
  alternativas.push({ fecha: d.fecha, dia: d.dia, horas: cercanas(d.horas, 3) });
}

const textoAlternativas = alternativas
  .map((a) => a.dia + ' ' + a.fecha + ': ' + a.horas.join(', '))
  .join('\n');

return [{
  json: {
    ...d,
    hora,
    email,
    estado: libre ? 'libre' : 'ocupado',
    dia: dia ? dia.dia : null,
    alternativas,
    textoAlternativas,
  },
}];

const d = $('Comprobar hueco').first().json;

return [{
  json: {
    ok: true,
    libre: true,
    reservada: false,
    fecha: d.fecha,
    dia: d.dia,
    hora: d.hora,
    mensaje: 'El ' + d.dia + ' ' + d.fecha + ' a las ' + d.hora + ' está libre.',
  },
}];

