const d = $('Comprobar hueco').first().json;

return [{
  json: {
    ok: true,
    reservada: true,
    fecha: d.fecha,
    dia: d.dia,
    hora: d.hora,
    email: d.email,
    mensaje:
      '¡Listo! Tu cita queda confirmada para el ' + d.dia + ' ' + d.fecha +
      ' a las ' + d.hora + '.' +
      (d.email ? ' Te envío la confirmación a ' + d.email + '.' : ''),
  },
}];

const d = $input.first().json;

if (d.estado === 'faltan_datos') {
  return [{
    json: {
      ok: false,
      reservada: false,
      motivo: 'faltan_datos',
      mensaje: 'Para reservar necesito al menos la fecha y la hora.',
    },
  }];
}

return [{
  json: {
    ok: false,
    reservada: false,
    motivo: 'ocupado',
    fecha: d.fecha,
    hora: d.hora,
    alternativas: d.alternativas,
    mensaje: d.textoAlternativas
      ? 'Lo siento, las ' + d.hora + ' del ' + d.fecha + ' no están disponibles. Tengo libre:\n' +
        d.textoAlternativas + '\n¿Cuál te viene mejor?'
      : 'Lo siento, ahora mismo no me queda ningún hueco libre en los próximos días.',
  },
}];

const d = $input.first().json;
const paso = d.paso;

const aMin = (h) => { const [a, b] = h.split(':').map(Number); return a * 60 + b; };
const dosCifras = (n) => String(n).padStart(2, '0');
const aTexto = (m) => dosCifras(Math.floor(m / 60)) + ':' + dosCifras(m % 60);

// La hora que el usuario escribe manda sobre la que extrae la IA: se la ha visto
// devolver time=null con la hora delante, y coger la primera opcion de su propia
// lista de alternativas (le pides 12:30 y reserva 12:15).
function horaDelTexto(txt) {
  const t = String(txt || '').toLowerCase();
  // Se evita el punto como separador suelto: '4.08' es una fecha, no las 04:08.
  const patrones = [
    /\blas\s+(\d{1,2})(?:\s*[:.,'’h]\s*(\d{2}))?/,
    /\b(\d{1,2})\s*[:'’]\s*(\d{2})\b/,
    /\b(\d{1,2})\s*[.,]\s*(\d{2})\s*h\b/,
    /\b(\d{1,2})\s*h\s*(\d{2})\b/,
    /\b(\d{1,2})\s*h\b/,
  ];
  for (const p of patrones) {
    const m = t.match(p);
    if (!m) continue;
    const h = Number(m[1]);
    const min = m[2] === undefined ? 0 : Number(m[2]);
    if (h < 24 && min < 60) return dosCifras(h) + ':' + dosCifras(min);
  }
  return null;
}


function rangos(horas) {
  const out = [];
  let ini = null;
  let prev = null;
  for (const h of horas) {
    const m = aMin(h);
    if (prev !== null && m === prev + paso) { prev = m; continue; }
    if (ini !== null) out.push(ini === prev ? aTexto(ini) : aTexto(ini) + '-' + aTexto(prev));
    ini = m;
    prev = m;
  }
  if (ini !== null) out.push(ini === prev ? aTexto(ini) : aTexto(ini) + '-' + aTexto(prev));
  return out.join(', ');
}

// Si preguntan por un día concreto, respondemos solo ese: por voz no se puede
// recitar la semana entera.
const dias = d.fecha ? d.libres.filter((x) => x.fecha === d.fecha) : d.libres;

const mensaje = dias.length
  ? dias.map((x) => x.dia + ' ' + x.fecha + ': ' + rangos(x.horas)).join('\n')
  : d.fecha
    ? 'No queda ningún hueco libre el ' + d.fecha + '.'
    : 'No queda ningún hueco libre en los próximos 7 días.';

return [{
  json: {
    ok: true,
    accion: 'disponibilidad',
    duracion_min: d.duracion,
    paso_min: d.paso,
    dias,
    mensaje,
  },
}];
